#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the kore-writer GitHub App and the judge machine user (#336, #355).
#
# Nothing here writes a secret to disk, to .env or to a command line: secrets
# are read with hidden input and go to the macOS keychain through the stdin of
# `security -i`. The only file that ever holds a secret is the App's .pem,
# which GitHub forces you to download; stage 3 deletes it.
#
#   bash tools/harness/wizards/identities.sh            # the real run
#   bash tools/harness/wizards/identities.sh --dry-run  # touches nothing
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5
ORG="corekraft"
REPO="corekraft/kore"
ACCOUNT="kore"
# No stage writes to a dotenv file; this keeps the library's hidden-entry helpers from reading one.
ENV_FILE=/dev/null

DRY_RUN=0
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    *) printf 'Unknown option %s. Usage: identities.sh [--dry-run]\n' "$arg" >&2; exit 2 ;;
  esac
done

# In a dry run nothing is opened, read, stored, deleted or called, and no prompt waits.
if (( DRY_RUN )); then
  open_url() { printf '  %s[dry run]%s would open %s\n' "$DIM" "$RESET" "$1"; }
  pause()    { :; }
  confirm()  { return 0; }
  ask()        { printf -v "$1" '%s' "dry-run-$1"; printf '  %s[dry run]%s %s (using a placeholder)\n' "$DIM" "$RESET" "$2"; }
  ask_secret() { printf -v "$1" '%s' "dry-run-secret"; printf '  %s[dry run]%s %s (using a placeholder)\n' "$DIM" "$RESET" "$2"; }
fi

# keychain_store SERVICE VALUE puts VALUE in the keychain under SERVICE (account kore).
# The value travels on stdin of `security -i`, never in a command line.
keychain_store() {
  if (( DRY_RUN )); then
    printf '  %s[dry run]%s would store keychain item %s\n' "$DIM" "$RESET" "$1"
    return 0
  fi
  if printf 'add-generic-password -U -s %s -a %s -w %s\n' "$1" "$ACCOUNT" "$2" | security -i >/dev/null 2>&1; then
    printf '  %s✓ stored%s keychain item %s\n' "$GREEN" "$RESET" "$1"
  else
    warn "could not store keychain item $1; is the login keychain unlocked?"
    return 1
  fi
}

banner "Kore role identities: the kore-writer App and the judge machine user"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check you are ready"
say "This creates two identities so writers and the judge stop sharing yours."
note "Writer: GitHub App kore-writer (contents:write, pull_requests:write, metadata:read)."
note "Judge:  a machine user with a fine-grained PAT."
if (( DRY_RUN )); then
  note "Dry run: nothing is opened, read, stored or deleted."
else
  command -v security >/dev/null 2>&1 || { warn "needs macOS's \`security\` tool"; exit 1; }
  gh auth status >/dev/null 2>&1 || { warn "run \`gh auth login\` as the repository owner first"; exit 1; }
  say "gh is signed in. The keychain items go in your login keychain."
fi
confirm "You are an owner of the $ORG organization, so continue?" || exit 1

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the kore-writer GitHub App"
open_url "https://github.com/organizations/$ORG/settings/apps/new"
step "GitHub App name: kore-writer. Homepage URL: https://github.com/$REPO."
step "Webhook: untick Active."
step "Repository permissions: Contents → Read and write; Pull requests → Read and write."
step "Leave Metadata as Read-only. Grant nothing else: no Actions, Administration or Workflows."
step "Where can this GitHub App be installed: Only on this account."
step "Click Create GitHub App."
ask WRITER_APP_ID "Paste the App ID from the top of the App's page:"
confirm "The App has exactly those three permissions?" || exit 1
keychain_store kore.writer.app-id "$WRITER_APP_ID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Store the App's private key in the keychain"
step "On the App's page, under Private keys, click Generate a private key."
step "Your browser downloads a .pem file; that is the only time the key touches disk."
ask PEM_PATH "Path of the downloaded .pem file:"
if (( DRY_RUN )); then
  keychain_store kore.writer.private-key "$PEM_PATH"
else
  [[ -f "$PEM_PATH" ]] || { warn "no file at $PEM_PATH"; exit 1; }
  # base64 keeps the multi-line PEM on one line for `security -i`.
  PEM_B64=$(base64 < "$PEM_PATH" | tr -d '\n')
  keychain_store kore.writer.private-key "$PEM_B64" || exit 1
  unset PEM_B64
fi
if (( DRY_RUN )); then
  note "[dry run] would delete $PEM_PATH"
elif confirm "Delete $PEM_PATH now? (rm -P overwrites it)"; then
  rm -P "$PEM_PATH" && printf '  %s✓ deleted%s the .pem\n' "$GREEN" "$RESET"
else
  warn "the key is still on disk at $PEM_PATH; delete it yourself"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Install the App on $REPO only"
open_url "https://github.com/organizations/$ORG/settings/apps/kore-writer/installations"
step "Click Install next to $ORG."
step "Choose Only select repositories, pick kore, and click Install."
step "The page you land on ends in /installations/<number>. Copy that number."
ask WRITER_INSTALLATION_ID "Paste the installation number:"
confirm "It is installed on kore and no other repository?" || exit 1
keychain_store kore.writer.installation-id "$WRITER_INSTALLATION_ID"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Create the judge machine user and its token"
step "In a private window, create a GitHub account for the judge (its own email address)."
ask JUDGE_LOGIN "Its username:"
open_url "https://github.com/$REPO/settings/access"
step "Invite $JUDGE_LOGIN as a collaborator with the Write role, then accept the invite as that user."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Signed in as $JUDGE_LOGIN: resource owner $ORG, repository access Only select repositories → kore."
step "Repository permissions: Contents → Read and write; Pull requests → Read and write; Metadata → Read-only."
step "Generate the token and copy it (it is shown once)."
ask_secret JUDGE_PAT "Paste the token (hidden):"
if (( DRY_RUN )); then
  note "[dry run] would check the token with GitHub"
else
  seen=$(GH_TOKEN="$JUDGE_PAT" gh api user --jq .login 2>/dev/null || true)
  if [[ "$seen" != "$JUDGE_LOGIN" ]]; then
    warn "GitHub did not recognise that token as $JUDGE_LOGIN"
    exit 1
  fi
  printf '  %s✓ verified%s the token belongs to %s\n' "$GREEN" "$RESET" "$seen"
fi
keychain_store kore.judge.pat "$JUDGE_PAT" || exit 1
unset JUDGE_PAT

say "Identities are in place. Next: \`harness ruleset sync --dry-run\`, then the owner's OK."
say "Break-glass after the sync removes your bypass is a logged manual ruleset edit."

finish
}

run_wizard "$@"; exit
